
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_scan_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_scan", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.884521552482989e+00, -4.785631897856206e+00, -4.647021893414946e+00, -4.454923757942999e+00, -4.192974998809499e+00, -3.843929012776643e+00, -3.393777460728831e+00, -2.839187166238046e+00, -2.197326709320885e+00, -1.502444047844217e+00, -8.610126124228888e-01, -6.257960238422819e-01, -6.257017739040301e-01, -5.317421371619734e-01, -3.626579618318302e-01, -1.960877086923029e-01, -7.911817549497922e-02, -2.112733026459889e-02, -2.956797969326537e-03, -1.408448835635363e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


